G=load()
def mk(g):
    cnt=Counter(x for r in g for x in r); bg=max(cnt,key=lambda c:-cnt[c]); sp=[c for c in cnt if c!=bg][0]
    H,W=len(g),len(g[0]); out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]==bg: continue
            touch=False
            for di in(-1,0,1):
                for dj in(-1,0,1):
                    if(di,dj)==(0,0): continue
                    a,b=i+di,j+dj
                    if 0<=a<H and 0<=b<W and g[a][b]!=sp: touch=True; break
                if touch: break
            if touch: out[i][j]=1
    return out
